import { test, expect } from '@playwright/test';

test.describe('Onboarding Tour Modal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
    await page.getByRole('button', { name: 'Start Tour' }).click();
  });

  test('should display the first step of the onboarding tour', async ({ page }) => {
    const firstStep = page.getByText('Welcome to the application!');
    await expect(firstStep).toBeVisible();
  });

  test('should advance to the second step when next is clicked', async ({ page }) => {
    await page.getByRole('button', { name: 'Next' }).click();
    const secondStep = page.getByText('Here is how to use the main features.');
    await expect(secondStep).toBeVisible();
  });
});
